window.kbPageData["views/entry/k-89eb4fb079f70fa6"] = {"key":"entry/k-89eb4fb079f70fa6","state":{"route":"entry/k-89eb4fb079f70fa6"},"node":{"id":"k-89eb4fb079f70fa6","mode":"k","title":"基本实现社会主义现代化","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#47","国考 2023 地市级 行测#1"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["modern"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"基本实现社会主义现代化是党的二十大报告所述全面建成社会主义现代化强国两步走战略的第一步目标，时间节点为2035年。","review":{"title":"基本实现社会主义现代化","type":"制度与规则","definition":"基本实现社会主义现代化是党的二十大报告所述全面建成社会主义现代化强国两步走战略的第一步目标，时间节点为2035年。","explanation":"到2035年的目标涵盖经济、科技、社会、生态等领域。在基本实现社会主义现代化的基础上，第二步是到本世纪中叶把我国建设成为综合国力和国际影响力领先的社会主义现代化强国。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"全面建成社会主义现代化强国的战略安排"}],"examFocus":{"政治理论必刷100题#47":"对照“十五五”经济社会发展座谈会讲话，核对这一时期的阶段目标，区分现代化建设各阶段的目标表述。","国考 2023 地市级 行测#1":"对照党的二十大报告的两步走安排，逐项核对经济、科技、产业和生态目标对应的阶段及实现程度。"}},"aspects":[{"title":"“十五五”规划谋划围绕的阶段目标","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题，选A。2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话要求，谋划这一时期的发展要围绕基本实现社会主义现代化，分领域确定目标任务。A将阶段目标写成了“全面实现社会主义现代化”。","evidence":"紧紧围绕基本实现社会主义现代化目标","qids":["政治理论必刷100题#47"]}]},{"title":"二十大报告的2035年发展目标","uses":[{"unit":"Q2","role":"直接考查","use":"本题选A，①人均国内生产总值达到中等发达国家水平、③建成现代化经济体系并基本实现新型工业化等两项正确。②的原文目标是进入创新型国家前列。④涉及的原文目标是碳排放达峰后稳中有降、美丽中国目标基本实现。⑤所述建成社会主义现代化强国对应本世纪中叶。","evidence":"碳排放达峰后稳中有降，生态环境\n根本好转，美丽中国目标基本实现","qids":["国考 2023 地市级 行测#1"]}]}],"sources":[{"id":"053a24013e87f6af","label":"基本实现社会主义现代化","topic":"党政制度与理论","category":"非时政","text":"1.基本实现社会主义现代化\n“基本实现社会主义现代化”是中国到 2035 年要实现的社会主义现代化目标，是全\n面建成社会主义现代化强国的第一阶段战略安排。第一阶段从 2020 年到 2035 年，基本\n实现社会主义现代化；第二阶段从 2035 年到本世纪中叶，建成富强民主文明和谐美丽的\n社会主义现代化强国。","source":{"doc":"41195a191a57c1c36332","first":23,"last":23,"page":23,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#47":{"paper":"政治理论必刷100题","n":47,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",14],"asrc":["国省考政治理论必刷100题.pdf",61],"card":"0d22e74f10d21a4306d29542","links":[{"id":"k-89eb4fb079f70fa6","role":"直接考查","why":"考查谋划“十五五”时期经济社会发展所围绕的现代化阶段目标。"}]},"国考 2023 地市级 行测#1":{"paper":"国考 2023 地市级 行测","n":1,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",1],"asrc":["f3ab652d8e31c5bbdabc.pdf",1],"card":"42f9f4e08a1799099f2484c2","links":[{"id":"k-89eb4fb079f70fa6","role":"直接考查","why":"两步走战略以二〇三五年基本实现社会主义现代化为第一阶段，以本世纪中叶建成社会主义现代化强国为第二阶段。"}]}},"terms":{},"references":{"twenty":{"name":"党的二十大报告（2022年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2022/art_d664717b51f54b9886bc371c5f3594ed.html"}},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-89eb4fb079f70fa6":[["政治理论必刷100题#47"],["国考 2023 地市级 行测#1"]]}};
